def build_regions(request):
    """Build a region graph from a floor request.

    Returns dict with:
      areas: list of positive int free-cell areas indexed by region
      neighbors: parallel list of lists of (neighbor_index, fee) pairs
      start: index of the region containing entry
    """
    width, height = request["size"]
    entry = tuple(request["entry"])
    blocked = request.get("blocked", [])
    walls = request.get("walls", [])

    # Mark blocked cells.
    blocked_set = set()
    for rect in blocked:
        x0, y0, x1, y1 = rect
        for x in range(x0, x1):
            for y in range(y0, y1):
                blocked_set.add((x, y))

    # Build fee map for each shared side (edge between adjacent free cells).
    # Key: frozenset of the two cell coordinates. Value: None if closed, else int fee.
    edge_fee = {}

    def add_edge(a, b, fee):
        key = frozenset((a, b))
        if key in edge_fee:
            cur = edge_fee[key]
            if cur is None or fee is None:
                edge_fee[key] = None
            else:
                edge_fee[key] = cur + fee
        else:
            edge_fee[key] = fee

    for wall in walls:
        seg = wall["segment"]
        fee = wall["fee"]
        x0, y0, x1, y1 = seg
        if fee is None:
            fee = None
        if x0 == x1:
            # vertical segment at x = x0, from y0 to y1
            x = x0
            for y in range(y0, y1):
                a = (x - 1, y)
                b = (x, y)
                if 0 <= x - 1 < width and 0 <= y < height:
                    add_edge(a, b, fee)
        elif y0 == y1:
            # horizontal segment at y = y0, from x0 to x1
            y = y0
            for x in range(x0, x1):
                a = (x, y - 1)
                b = (x, y)
                if 0 <= x < width and 0 <= y - 1 < height:
                    add_edge(a, b, fee)

    # Union-find over free cells, connecting across zero-fee edges.
    parent = {}

    def find(c):
        parent.setdefault(c, c)
        while parent[c] != c:
            parent[c] = parent[parent[c]]
            c = parent[c]
        return c

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    # Initialize all free cells.
    for x in range(width):
        for y in range(height):
            if (x, y) not in blocked_set:
                parent[(x, y)] = (x, y)

    # Union across zero-fee edges.
    for key, fee in edge_fee.items():
        if fee == 0:
            a, b = tuple(key)
            union(a, b)

    # Assign region indices.
    region_index = {}
    regions = []
    for x in range(width):
        for y in range(height):
            c = (x, y)
            if c in blocked_set:
                continue
            r = find(c)
            if r not in region_index:
                region_index[r] = len(regions)
                regions.append(r)
            # area counted below

    areas = [0] * len(regions)
    cell_region = {}
    for x in range(width):
        for y in range(height):
            c = (x, y)
            if c in blocked_set:
                continue
            r = find(c)
            idx = region_index[r]
            areas[idx] += 1
            cell_region[c] = idx

    # Build neighbors from positive-fee edges (and closed edges are excluded).
    neighbors = [[] for _ in regions]
    for key, fee in edge_fee.items():
        if fee is None or fee == 0:
            continue
        a, b = tuple(key)
        if a in blocked_set or b in blocked_set:
            continue
        ia = cell_region[a]
        ib = cell_region[b]
        if ia == ib:
            continue
        neighbors[ia].append((ib, fee))
        neighbors[ib].append((ia, fee))

    start = cell_region[entry]

    return {"areas": areas, "neighbors": neighbors, "start": start}

import heapq


def fee_areas(regions):
    """Compute area_by_fee and unreachable from a region graph."""
    areas = regions["areas"]
    neighbors = regions["neighbors"]
    start = regions["start"]

    n = len(areas)
    dist = [None] * n
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if dist[u] is not None and d > dist[u]:
            continue
        for v, fee in neighbors[u]:
            nd = d + fee
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))

    area_by_fee = {}
    unreachable = 0
    for i in range(n):
        if dist[i] is None:
            unreachable += areas[i]
        else:
            key = str(dist[i])
            area_by_fee[key] = area_by_fee.get(key, 0) + areas[i]

    return {"area_by_fee": area_by_fee, "unreachable": unreachable}

